package com.example.campsitelottery

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Documentation generated by Claude
 * Tests for [RatingPolicy].
 */
class RatingPolicyTest {

    @Test
    fun isValid_acceptsOneToFiveOnly() {
        assertFalse(RatingPolicy.isValid(0))
        for (stars in 1..5) assertTrue(RatingPolicy.isValid(stars))
        assertFalse(RatingPolicy.isValid(6))
        assertFalse(RatingPolicy.isValid(-1))
    }

    @Test
    fun apply_firstRatingAddsToSumAndCount() {
        val result = RatingPolicy.apply(RatingPolicy.Totals(), previousStars = null, newStars = 4)
        assertEquals(RatingPolicy.Totals(sum = 4, count = 1), result)
        assertEquals(4.0, result.average, 0.0001)
    }

    @Test
    fun apply_secondUserIsAveraged() {
        val result = RatingPolicy.apply(RatingPolicy.Totals(sum = 4, count = 1), null, 1)
        assertEquals(RatingPolicy.Totals(sum = 5, count = 2), result)
        assertEquals(2.5, result.average, 0.0001)
    }

    @Test
    fun apply_changingARatingKeepsTheCount() {
        val result = RatingPolicy.apply(RatingPolicy.Totals(sum = 7, count = 2), previousStars = 2, newStars = 5)
        assertEquals(RatingPolicy.Totals(sum = 10, count = 2), result)
    }

    @Test(expected = IllegalArgumentException::class)
    fun apply_rejectsOutOfRangeStars() {
        RatingPolicy.apply(RatingPolicy.Totals(), null, 6)
    }

    @Test
    fun average_isZeroWithNoRatings() {
        assertEquals(0.0, RatingPolicy.Totals().average, 0.0)
    }

    @Test
    fun canRate_ownerCannotRateOwnCampsite() {
        assertFalse(RatingPolicy.canRate(ownerId = "owner", userId = "owner"))
        assertTrue(RatingPolicy.canRate(ownerId = "owner", userId = "guest"))
        assertFalse(RatingPolicy.canRate(ownerId = "owner", userId = ""))
    }

    @Test
    fun summary_formatsCountAndAverage() {
        assertEquals("No ratings yet", RatingPolicy.summary(RatingPolicy.Totals()))
        assertEquals("4.0 ★ (1 rating)", RatingPolicy.summary(RatingPolicy.Totals(4, 1)))
        assertEquals("4.3 ★ (3 ratings)", RatingPolicy.summary(RatingPolicy.Totals(13, 3)))
    }

    @Test
    fun newCampsite_hasNoRatings() {
        val totals = RatingPolicy.totalsOf(Campsite())
        assertEquals(0L, totals.sum)
        assertEquals(0, totals.count)
    }
}
